import{z as i,x as s,o as A,c as d,q as r,j as l,D as B,d as e,s as o,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"案例与收束","description":"","frontmatter":{"title":"案例与收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ot-case-map.md","filePath":"quant/ot-case-map.md","lastUpdated":1791413859000}'),p={name:"quant/ot-case-map.md"};function C(u,a,D,m,f,h){const t=s("Mermaid");return A(),d("div",null,[a[2]||(a[2]=r('<h1 id="案例与收束" tabindex="-1">案例与收束 <a class="header-anchor" href="#案例与收束" aria-label="Permalink to &quot;案例与收束&quot;">​</a></h1><div class="epigraph"><p>结构化产品的考试不出在定价题上，出在条款之外：发行人倒下、障碍堆积、指数退场——每一问考的都是条款、账本与合同哪一层先接住冲击。</p><footer>—— 据香港证监会雷曼相关回购安排公告与 BIS Quarterly Review 相关评述整理</footer></div><p><a href="/quant/ot-portfolio-regulation">上一课</a>把组合与监管收进四层程序。九课走完，本课用三个案例做收束：2008 年的雷曼迷你债券考发行安全，2024 年初的雪球集中敲入考障碍堆积，LIBOR 退场考票息挂钩指数的合同地位。每个案例停在本课程立过的判据上，本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>案例教学的风险是把故事当知识。本课的问题只有一个：课程立的判据能否事前写进系统与限额，而不是事后解释情节。三个案例各考一课：雷曼考<a href="/quant/ot-counterparty-credit">对手方信用管理</a>立的「结构安全不等于发行安全」；雪球敲入考<a href="/quant/ot-barrier-portfolios">障碍结构的组合</a>立的分桶聚合与<a href="/quant/snowball-dealer-hedging">对冲商堆积</a>立的同步流量；LIBOR 考<a href="/quant/ot-isda-documentation">文档体系</a>立的「条款即合同」。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>案例一：2008 年雷曼兄弟破产。以「迷你债券」名义发行的零售结构化票据由雷曼关联实体担保，发行人倒下后票据按违约清偿处置，产品挂钩的抵押池并未消失，但持有人拿到的是清偿价值；香港市场余额以百亿港元计，分销行最终向多数持有人安排回购。判据有两条：票据是发行人的无担保负债，产品的对冲结构再完好也替换不了发行人信用；适当性若不评估发行人主体，等于只考了卷面不考了对手。这两条正是<a href="/quant/ot-counterparty-credit">对手方信用管理</a>里投资者侧与销售层的全部内容。</p><p><span class="marginnote">术语翻译：「迷你债券」名字里虽有「债」，本质是结构化票据——你的钱进挂钩工具，偿付承诺挂在发行与担保实体身上。发行实体一倒，产品再「结构完好」也只剩违约清偿，名字里的「债券」二字不构成任何保护。</span></p><p>案例二：2024 年初。A 股指数快速下行，存续雪球的敲入线集中分布的区间被相继击穿，发行台的对冲流量在同一带上叠加，市场讨论把「敲入」与「踩踏」连成一句。判据要拆开：敲入前，账本 gamma 按障碍水平与时钟分桶聚合，峰值流量对深度之比是事前可算的量；敲入后，凸性消失、库存再平衡是另一段流量。按<a href="/quant/ot-barrier-portfolios">障碍结构的组合</a>聚合、按<a href="/quant/ot-issuer-hedging">发行方视角</a>归因的台，事前就有这条带的风险地图；只有逐笔限额的台，事后的叙事替代不了地图。</p><p><span class="marginnote">直觉类比：雪球集中敲入像多条河道在同一个窄口汇流——每艘船（每笔对冲）单独看都不大，但在同一价格带同时转向，窄口的水位就不由任何一艘船决定。事前画出「窄口在哪、船有多少」，就是这张风险地图。</span></p><p>案例三：LIBOR 退场（2014–2023）。挂钩利率的浮动票息结构与含 early termination 条款的票据整体迁移：<a href="/quant/multi-curve-ois">多曲线框架</a>重建贴现与投影，fallback 利差让存续合约过渡，确认书逐笔修订。判据是<a href="/quant/rc-case-map">利率信用收束课</a>同一案例立过的：挂钩指数的合同地位是条款的一部分——浮动票息 FCN 的「固定收益增强」标签下，连票息的参考利率都是一栏合同字段。</p><p><span class="marginnote">常见误区：以为挂钩指数消失只是「换个报价来源」。LIBOR 退场要同时动贴现曲线、fallback 利差、确认书条款三层，漏改一层就会出现同一天两种利率各记一笔账——估值对不上不是模型问题，是合同没改完的法律问题。</span></p>',12)),(A(),l(n,null,{default:B(()=>[o(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22%E9%9B%B7%E6%9B%BC%202008%EF%BC%9A%E5%8F%91%E8%A1%8C%E5%AE%89%E5%85%A8%22%5D%20--%3E%20J1%5B%22%E5%88%A4%E6%8D%AE%EF%BC%9A%E7%A5%A8%E6%8D%AE%E6%98%AF%E6%97%A0%E6%8B%85%E4%BF%9D%E8%B4%9F%E5%80%BA%22%5D%0A%20%20C2%5B%22%E9%9B%AA%E7%90%83%E6%95%B2%E5%85%A5%202024%EF%BC%9A%E9%9A%9C%E7%A2%8D%E5%A0%86%E7%A7%AF%22%5D%20--%3E%20J2%5B%22%E5%88%A4%E6%8D%AE%EF%BC%9A%E5%B3%B0%E5%80%BC%E6%B5%81%E9%87%8F%E5%AF%B9%E6%B7%B1%E5%BA%A6%E4%BA%8B%E5%89%8D%E5%8F%AF%E7%AE%97%22%5D%0A%20%20C3%5B%22LIBOR%20%E9%80%80%E5%9C%BA%EF%BC%9A%E6%8C%87%E6%95%B0%E5%90%88%E5%90%8C%E5%9C%B0%E4%BD%8D%22%5D%20--%3E%20J3%5B%22%E5%88%A4%E6%8D%AE%EF%BC%9A%E6%8C%82%E9%92%A9%E6%8C%87%E6%95%B0%E6%98%AF%E6%9D%A1%E6%AC%BE%E5%AD%97%E6%AE%B5%22%5D%0A%20%20J1%20--%3E%20END%5B%22%E6%94%B6%E6%9D%9F%EF%BC%9A%E6%9D%A1%E6%AC%BE%E5%8D%B3%E4%BB%B7%E6%A0%BC%EF%BC%8C%E5%8F%91%E8%A1%8C%E5%8D%B3%E8%B4%A6%E6%9C%AC%22%5D%0A%20%20J2%20--%3E%20END%0A%20%20J3%20--%3E%20END%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("三个案例合起来给出本课程的方法论。其一，条款即价格：谱系轴上的每个字段、每条监控时钟、每个挂钩指数，都是定价与风险的输入，字段管理先于公式管理。其二，发行即账本：卖断收价差、留存养对冲，利润逐日实现，残差分桶认领，归因留出没人解释的位置。其三，法律与信用决定谁付账：净额集划出暴露的边界，CSA 迁移暴露的时点，发行人信用价差写回票息——定价的最后一层永远是「对手付不付得起」。与姊妹课程对照："),E("a",{href:"/quant/rc-case-map"},"利率信用收束"),e("把价格拆到资金与约束层，本课程把条款拆到字段与合同层，两层在报价单上会合。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"三个案例的年份横跨十六年，考题却同构：冲击都从「条款之外」进来——主体违约、群体对冲、指数消失；课程九课的分工就是把条款之外的三层（账本、对手、合同）各写成可检验的判据。")],-1)),(A(),l(n,null,{default:B(()=>[o(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22%E6%9D%A1%E6%AC%BE%E4%B9%8B%E5%A4%96%E7%9A%84%E5%86%B2%E5%87%BB%22%5D%20--%3E%20L1%7B%22%E5%93%AA%E4%B8%80%E5%B1%82%E5%85%88%E6%8E%A5%E4%BD%8F%3F%22%7D%0A%20%20L1%20--%3E%7C%22%E5%8F%91%E8%A1%8C%E4%BA%BA%E5%80%92%E4%B8%8B%22%7C%20CD%5B%22%E5%AF%B9%E6%89%8B%E5%B1%82%EF%BC%9A%E5%8F%91%E8%A1%8C%E4%BA%BA%E4%BF%A1%E7%94%A8%22%5D%0A%20%20L1%20--%3E%7C%22%E7%BE%A4%E4%BD%93%E5%AF%B9%E5%86%B2%22%7C%20BK%5B%22%E8%B4%A6%E6%9C%AC%E5%B1%82%EF%BC%9A%E9%9A%9C%E7%A2%8D%E5%B8%A6%E8%81%9A%E5%90%88%22%5D%0A%20%20L1%20--%3E%7C%22%E6%8C%87%E6%95%B0%E6%B6%88%E5%A4%B1%22%7C%20LG%5B%22%E5%90%88%E5%90%8C%E5%B1%82%EF%BC%9Afallback%E6%9D%A1%E6%AC%BE%22%5D%0A%20%20CD%20--%3E%20R1%5B%22%E7%A5%A8%E6%81%AF%E5%86%99%E5%9B%9E%E4%BF%A1%E7%94%A8%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20BK%20--%3E%20R2%5B%22%E5%B3%B0%E5%80%BC%E6%B5%81%E9%87%8F%E5%AF%B9%E6%B7%B1%E5%BA%A6%E4%BA%8B%E5%89%8D%E5%8F%AF%E7%AE%97%22%5D%0A%20%20LG%20--%3E%20R3%5B%22%E7%A1%AE%E8%AE%A4%E4%B9%A6%E9%80%90%E7%AC%94%E4%BF%AE%E8%AE%A2%E8%BF%81%E7%A7%BB%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写销售纠纷史与监管处罚史，案例只取与判据相接的截面；金额与时点引用带公开出处，不做估算。敲入潮的定量归因属于市场微观结构的计量专题，<a href="/quant/snowball-dealer-hedging">堆积</a>课已给边界，不在本课下结论。收束之后，场外与场内的对照、全球制度差异另有课程接续。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>雷曼 2008：票据是发行人的无担保负债，适当性必须考对手主体，不只考结构。</li><li>雪球敲入 2024：障碍带事前聚合、峰值流量对深度是可算的量，叙事替代不了风险地图。</li><li>LIBOR 退场：挂钩指数是条款字段，浮动票息结构整体迁移靠合同机制。</li><li>三条方法论贯穿九课：条款即价格、发行即账本、法律与信用定谁付账。</li><li>出处：香港证监会雷曼相关回购安排公告；BIS Quarterly Review 相关评述；判据出自本课程各课，见文中链接。</li></ul>',4))])}const q=i(p,[["render",C]]);export{c as __pageData,q as default};
